package cn.huankan.event;
import cn.huankan.collector.SdmxCsv;import cn.huankan.evidence.EvidenceService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.util.*;import java.time.*;import java.math.*;
@Service public class MacroChangeService {
 private static String chineseName(String id){return switch(id){case "EXR.D.USD.EUR.SP00.A"->"欧元兑美元官方参考汇率";case "EXR.D.JPY.EUR.SP00.A"->"欧元兑日元官方参考汇率";case "EXR.D.GBP.EUR.SP00.A"->"欧元兑英镑官方参考汇率";case "EXR.D.CNY.EUR.SP00.A"->"欧元兑人民币官方参考汇率";case "FM.B.U2.EUR.4F.KR.DFR.LEV"->"欧洲央行存款便利利率";case "FM.B.U2.EUR.4F.KR.MRR_FR.LEV"->"欧洲央行主要再融资固定利率";case "FM.B.U2.EUR.4F.KR.MLFR.LEV"->"欧洲央行边际贷款便利利率";default->"中文名称待核验";};}
 private final JdbcTemplate db;public MacroChangeService(JdbcTemplate db){this.db=db;}
 public Object catalog(int page,String source){if(page<0||page>10000)throw new IllegalArgumentException("分页无效");return db.queryForList("SELECT s.*,r.name publisher,r.region,o.observation_date latest_period,o.value::text latest_value FROM macro_series s JOIN source_registry r ON r.id=s.source_id JOIN source_license l ON l.source_id=s.source_id LEFT JOIN LATERAL(SELECT * FROM macro_observation WHERE series_id=s.id ORDER BY observation_date DESC,version DESC LIMIT 1)o ON true WHERE l.status='APPROVED' AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND (?::text IS NULL OR s.source_id=?) ORDER BY s.source_id,s.id LIMIT 50 OFFSET ?",source,source,page*50);}
 public Object overview(){var summary=db.queryForMap("SELECT (SELECT count(DISTINCT source_id) FROM macro_series) official_sources,(SELECT count(*) FROM macro_series) series,(SELECT count(*) FROM macro_observation) observations,(SELECT count(*) FROM macro_history_version) local_versions,(SELECT count(*) FROM macro_history_version WHERE source_vintage_at IS NOT NULL) official_revisions,(SELECT count(*) FROM macro_series s WHERE (SELECT count(DISTINCT observation_date) FROM macro_observation WHERE series_id=s.id)>1) candidate_comparable_series,(SELECT count(*) FROM macro_observation WHERE value IS NULL OR observation_status NOT IN('A','P')) pending_data");
  int verifiedSeries=0,comparableSeries=0,changes=0,blocked=0,verifiedObservations=0;
  for(var s:db.queryForList("SELECT id FROM macro_series ORDER BY id")){
   var result=detail(s.get("id").toString(),0,null,null,null,null);var rows=(List<Map<String,Object>>)result.get("observations");if(rows==null)continue;
   var inputs=new ArrayList<MacroChangeEngine.Observation>();for(var row:rows){Map<String,String> m=(Map<String,String>)row.getOrDefault("metadata",Map.of());boolean valid=row.get("metadata")!=null;inputs.add(new MacroChangeEngine.Observation(row.get("evidence_id").toString(),s.get("id").toString(),((java.sql.Date)row.get("observation_date")).toLocalDate(),valid?new BigDecimal(row.get("original_value").toString()):null,m));if(valid)verifiedObservations++;}
   if(inputs.stream().anyMatch(o->o.value()!=null))verifiedSeries++;int seriesChanges=0;for(int i=0;i<inputs.size();i++){var calc=MacroChangeEngine.calculate(inputs.get(i),i+1<inputs.size()?inputs.get(i+1):null,true);if(calc.get("delta")!=null)seriesChanges++;else blocked++;}changes+=seriesChanges;if(seriesChanges>0)comparableSeries++;
  }
  summary.put("verified_series",verifiedSeries);summary.put("verified_observations",verifiedObservations);summary.put("comparable_series",comparableSeries);summary.put("calculable_changes",changes);summary.put("non_comparable",blocked);summary.put("audit_scope","各序列最近100个不同观测期；不是无限历史统计");summary.put("source_anomalies",db.queryForObject("SELECT count(DISTINCT s.source_id) FROM macro_series s JOIN LATERAL(SELECT status FROM ingestion_job WHERE source_id=s.source_id ORDER BY started_at DESC LIMIT 1)j ON true WHERE j.status='FAILED'",Integer.class));return summary;}
 public Map<String,Object> detail(String series,int page,LocalDate from,LocalDate to,Instant asOf,LocalDate rangeStart){
  if(series==null||!series.matches("[A-Z0-9._]{5,100}")||page<0||page>10000||from!=null&&to!=null&&from.isAfter(to)||asOf!=null&&asOf.isAfter(Instant.now().plusSeconds(5)))throw new IllegalArgumentException("查询参数无效");
  var meta=db.queryForList("SELECT s.*,r.name publisher,r.region FROM macro_series s JOIN source_registry r ON r.id=s.source_id JOIN source_license l ON l.source_id=s.source_id WHERE s.id=? AND l.status='APPROVED' AND l.storage_allowed AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now())",series);var out=new LinkedHashMap<String,Object>();if(meta.isEmpty()){out.put("observations",List.of());out.put("status","暂无真实指标");return out;}var definition=meta.getFirst();definition.put("indicator_id",series);definition.put("original_series_id",series);definition.put("name_zh",chineseName(series));definition.put("indicator_category",series.startsWith("EXR.")?"官方参考汇率":series.startsWith("FM.")?"官方政策利率":"口径待核验");out.put("definition",definition);Instant cutoff=asOf==null?Instant.now():asOf;
  var rows=db.queryForList("SELECT DISTINCT ON(m.observation_date) m.*,m.value::text original_value,r.raw_content,r.raw_content_hash,r.source_url,r.published_at source_published_at,r.first_seen_at available_at,r.collected_at,r.ingested_at,r.ingestion_kind FROM macro_observation m JOIN raw_evidence r ON r.id=m.evidence_id WHERE m.series_id=? AND r.collected_at<=? AND r.ingested_at<=? AND (r.published_at IS NULL OR r.published_at<=?) AND (?::date IS NULL OR m.observation_date>=?) AND (?::date IS NULL OR m.observation_date<=?) ORDER BY m.observation_date DESC,m.version DESC LIMIT 100 OFFSET ?",series,java.sql.Timestamp.from(cutoff),java.sql.Timestamp.from(cutoff),java.sql.Timestamp.from(cutoff),from,from,to,to,page*100);
  var verified=new ArrayList<MacroChangeEngine.Observation>();var cache=new HashMap<String,List<SdmxCsv.Observation>>();
  for(var row:rows){byte[] bytes=(byte[])row.remove("raw_content");boolean intact=EvidenceService.hash(bytes).equals(row.get("raw_content_hash"));var date=((java.sql.Date)row.get("observation_date")).toLocalDate();SdmxCsv.Observation literal=null;
   try{if(intact){var parsed=cache.computeIfAbsent(row.get("raw_content_hash").toString(),h->SdmxCsv.parse(bytes,series));literal=parsed.stream().filter(o->o.date().equals(date)).findFirst().orElse(null);}}catch(IllegalArgumentException ignored){}
   boolean matched=literal!=null&&literal.value()!=null&&row.get("value") instanceof BigDecimal value&&literal.value().compareTo(value)==0&&Objects.equals(literal.status(),row.get("observation_status"));row.put("hash_passed",intact);row.put("verification_status",matched?"原始CSV字段核验通过":"原始字段核验不足");row.put("official_vintage_id",null);row.put("local_version_id",row.get("version"));
   if(matched){row.put("original_value",literal.value().toPlainString());row.put("metadata",literal.metadata());verified.add(new MacroChangeEngine.Observation(row.get("evidence_id").toString(),series,date,literal.value(),literal.metadata()));}
  }
  // Keep unverified periods as barriers: never skip a missing or corrupt intermediate input.
  var inputs=new ArrayList<MacroChangeEngine.Observation>();for(var row:rows){var found=verified.stream().filter(o->o.id().equals(row.get("evidence_id").toString())).findFirst();inputs.add(found.orElseGet(()->new MacroChangeEngine.Observation(row.get("evidence_id").toString(),series,((java.sql.Date)row.get("observation_date")).toLocalDate(),null,Map.of())));}
  if(!verified.isEmpty()){var literal=verified.getFirst().metadata();definition.put("unit_scale",literal.get("UNIT_MULT"));definition.put("seasonal_adjustment",literal.getOrDefault("ADJUSTMENT",literal.getOrDefault("SEASONAL_ADJUSTMENT","官方未提供；不推断季调")));definition.put("quote_direction",literal.get("CURRENCY_DENOM")==null?"不适用":"每1 "+literal.get("CURRENCY_DENOM")+" 对应 "+literal.get("UNIT"));}
  out.put("observations",rows);out.put("page",page);out.put("page_size",100);out.put("has_next",rows.size()==100);out.put("calculations",MacroChangeEngine.analyze(inputs,rangeStart));out.put("revision_status","官方历史修订信息尚未取得");out.put("historical_availability",asOf==null?"当前已取得证据；官方发布时间未知时不能复原历史公开状态":"仅为本地可知快照；缺少官方公开时间，不能完成精确历史实时回测");
  out.put("versions",db.queryForList("SELECT h.id,h.observation_date,h.value::text original_value,h.version,h.action,h.collected_at,h.source_published_at,h.source_vintage_at,h.content_hash,lag(h.value::text) OVER(PARTITION BY h.observation_date ORDER BY h.version) previous_local_value,(h.value-lag(h.value) OVER(PARTITION BY h.observation_date ORDER BY h.version))::text local_delta,r.sha256 response_hash,r.url FROM macro_history_version h JOIN official_response r ON r.id=h.response_id WHERE h.series_id=? AND h.collected_at<=? ORDER BY h.observation_date DESC,h.version DESC LIMIT 100 OFFSET ?",series,java.sql.Timestamp.from(cutoff),page*100));
  out.put("events",db.queryForList("SELECT e.id,e.original_title,e.chinese_title,r.published_at,r.source_url,m.observation_date,m.evidence_id,'来源元数据确定的观测关系；非政策公告关联' link_basis FROM macro_observation m JOIN financial_event e ON e.evidence_id=m.evidence_id JOIN raw_evidence r ON r.id=m.evidence_id WHERE m.series_id=? ORDER BY m.observation_date DESC,m.version DESC,e.id LIMIT 50 OFFSET ?",series,page*50));
  ((List<Map<String,Object>>)out.get("events")).removeIf(e->verified.stream().noneMatch(o->o.id().equals(e.get("evidence_id").toString())));
  out.put("sources",db.queryForList("SELECT s.id,s.name,s.enabled,j.status,j.http_status,j.error_code,j.finished_at FROM source_registry s LEFT JOIN LATERAL(SELECT * FROM ingestion_job WHERE source_id=s.id ORDER BY started_at DESC LIMIT 1)j ON true WHERE s.id=(SELECT source_id FROM macro_series WHERE id=?)",series));return out;
 }
}




